import{_ as p,a0 as r,w as n,s as o,ao as d,I as l,x as e,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"用 coredumpctl 更好地記錄 bug | LCTT x X-CMD","titleTemplate":false,"description":"用 coredumpctl 更好地記錄 bug | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 coredumpctl 更好地記錄 bug | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 coredumpctl 更好地記錄 bug | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20171110 File better bugs with coredumpctl","title":"用 coredumpctl 更好地記錄 bug","tag":"201711","desc":""},"relativePath":"201711/20171110 File better bugs with coredumpctl.md","filePath":"[post].md"}'),g={name:"201711/20171110 File better bugs with coredumpctl.md"};function u(b,t,h,k,c,f){const s=r("Link");return n(),o("div",null,[t[21]||(t[21]=d('<h1 id="用-coredumpctl-更好地記錄-bug" tabindex="-1">用 coredumpctl 更好地記錄 bug <a class="header-anchor" href="#用-coredumpctl-更好地記錄-bug" aria-label="Permalink to “用 coredumpctl 更好地記錄 bug”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/11/coredump.png-945x400.jpg" alt=""></p><p>一個不幸的事實是，所有的軟件都有 bug，一些 bug 會導致系統崩潰。當它出現的時候，它經常會在磁盤上留下一個被稱為“<ruby>核心轉儲<rt>core dump</rt></ruby>”的數據文件。該文件包含有關係統崩潰時的相關數據，可能有助於確定發生崩潰的原因。通常開發者要求提供 “<ruby>回溯<rt>backtrace</rt></ruby>” 形式的數據，以顯示導致崩潰的指令流。開發人員可以使用它來修復 bug 以改進系統。如果系統發生了崩潰，以下是如何輕鬆生成 <ruby>回溯<rt>backtrace</rt></ruby> 的方法。</p><h3 id="從使用-coredumpctl-開始" tabindex="-1">從使用 coredumpctl 開始 <a class="header-anchor" href="#從使用-coredumpctl-開始" aria-label="Permalink to “從使用 coredumpctl 開始”">​</a></h3>',4)),l("p",null,[t[1]||(t[1]=e("大多數 Fedora 系統使用",-1)),i(s,{href:"https://github.com/abrt/abrt"},{default:a(()=>[...t[0]||(t[0]=[e("自動錯誤報告工具（ABRT）",-1)])]),_:1}),t[2]||(t[2]=e("來自動捕獲崩潰文件並記錄 bug。但是，如果你禁用了此服務或刪除了該軟件包，則此方法可能會有所幫助。",-1))]),t[22]||(t[22]=d('<p>如果你遇到系統崩潰，請首先確保你運行的是最新的軟件。更新通常包含修復程序，這些更新通常含有已經發現的會導致嚴重錯誤和崩潰的錯誤的修復。當你更新後，請嘗試重現導致錯誤的情況。</p><p>如果崩潰仍然發生，或者你已經在運行最新的軟件，那麼可以使用有用的 <code>coredumpctl</code> 工具。此程序可幫助查找和處理崩潰。要查看系統上所有核心轉儲列表，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>coredumpctl list</span></span></code></pre></div><p>如果你看到比預期長的列表，請不要感到驚訝。有時系統組件在後台默默地崩潰，並自行恢復。快速查找今天的轉儲的簡單方法是使用 <code>-since</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>coredumpctl list --since=today</span></span></code></pre></div><p>“PID” 列包含用於標識轉儲的進程 ID。請注意這個數字，因為你會之後再用到它。或者，如果你不想記住它，使用下面的命令將它賦值給一個變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MYPID=&lt;PID&gt;</span></span></code></pre></div><p>要查看關於核心轉儲的信息，請使用此命令（使用 <code>$MYPID</code> 變量或替換 PID 編號）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>coredumpctl info $MYPID</span></span></code></pre></div><h3 id="安裝-debuginfo-包" tabindex="-1">安裝 debuginfo 包 <a class="header-anchor" href="#安裝-debuginfo-包" aria-label="Permalink to “安裝 debuginfo 包”">​</a></h3><p>在核心轉儲中的數據以及原始代碼中的指令之間調試符號轉義。這個符號數據可能相當大。與大多數用户運行在 Fedora 系統上的軟件包不同，符號以 “debuginfo” 軟件包的形式安裝。要確定你必須安裝哪些 debuginfo 包，請先運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>coredumpctl gdb $MYPID</span></span></code></pre></div>',12)),l("p",null,[t[4]||(t[4]=e("這可能會在屏幕上顯示大量信息。最後一行可能會告訴你使用 ",-1)),t[5]||(t[5]=l("code",null,"dnf",-1)),t[6]||(t[6]=e(" 安裝更多的 debuginfo 軟件包。",-1)),i(s,{href:"https://fedoramagazine.org/howto-use-sudo/"},{default:a(()=>[...t[3]||(t[3]=[e("用 sudo ",-1)])]),_:1}),t[7]||(t[7]=e("運行該命令以安裝：",-1))]),t[23]||(t[23]=d(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf debuginfo-install &lt;packages...&gt;</span></span></code></pre></div><p>然後再次嘗試 <code>coredumpctl gdb $MYPID</code> 命令。<strong>你可能需要重複執行此操作</strong>，因為其他符號會在回溯中展開。</p><h3 id="捕獲回溯" tabindex="-1">捕獲回溯 <a class="header-anchor" href="#捕獲回溯" aria-label="Permalink to “捕獲回溯”">​</a></h3><p>在調試器中運行以下命令以記錄信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>set logging file mybacktrace.txt</span></span>
<span class="line"><span>set logging on</span></span></code></pre></div><p>你可能會發現關閉分頁有幫助。對於長的回溯，這可以節省時間。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>set pagination off</span></span></code></pre></div><p>現在運行回溯：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>thread apply all bt full</span></span></code></pre></div><p>現在你可以輸入 <code>quit</code> 來退出調試器。<code>mybacktrace.txt</code> 包含可附加到 bug 或問題的追蹤信息。或者，如果你正在與某人實時合作，則可以將文本上傳到 pastebin。無論哪種方式，你現在可以向開發人員提供更多的幫助來解決問題。</p><hr><p>作者簡介：</p><p>Paul W. Frields</p><p>Paul W. Frields 自 1997 年以來一直是 Linux 用户和愛好者，並於 2003 年在 Fedora 發佈不久後加入 Fedora。他是 Fedora 項目委員會的創始成員之一，從事文檔、網站發佈、宣傳、工具鏈開發和維護軟件。他於 2008 年 2 月至 2010 年 7 月加入 Red Hat，擔任 Fedora 項目負責人，現任紅帽公司工程部經理。他目前和妻子和兩個孩子住在弗吉尼亞州。</p><hr>`,15)),l("p",null,[t[9]||(t[9]=e("via: ",-1)),i(s,{href:"https://fedoramagazine.org/file-better-bugs-coredumpctl/"},{default:a(()=>[...t[8]||(t[8]=[e("https://fedoramagazine.org/file-better-bugs-coredumpctl/",-1)])]),_:1})]),l("p",null,[t[13]||(t[13]=e("作者：",-1)),i(s,{href:"https://fedoramagazine.org/author/pfrields/"},{default:a(()=>[...t[10]||(t[10]=[e("Paul W. Frields",-1)])]),_:1}),t[14]||(t[14]=e(" 譯者：",-1)),i(s,{href:"https://github.com/geekpi"},{default:a(()=>[...t[11]||(t[11]=[e("geekpi",-1)])]),_:1}),t[15]||(t[15]=e(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:a(()=>[...t[12]||(t[12]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[18]||(t[18]=e("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[16]||(t[16]=[e("LCTT",-1)])]),_:1}),t[19]||(t[19]=e(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:a(()=>[...t[17]||(t[17]=[e("Linux中國",-1)])]),_:1}),t[20]||(t[20]=e(" 榮譽推出",-1))])])}const T=p(g,[["render",u]]);export{C as __pageData,T as default};
